import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};

 await call('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html'});
 for(let i=0;i<300;i++){if(await evaluate('Boolean(window.review)'))break;await new Promise(r=>setTimeout(r,100));}
 const result=await evaluate(`(async()=>{
  const check=(v,label)=>{if(!v)throw Error(label);},wait=ms=>new Promise(r=>setTimeout(r,ms)),g=review.game;
  await g.assetsReady;g.setPaused(true);g.audio.stopAllAudio();g.audio.setMuted(false);g.audio.setMasterVolume(.4);
  const {GardenAudio}=await import('/src/js/garden/GardenAudio.js'),a=new GardenAudio(g.audio),s={stage:'RUNNING',time:1};
  a.unlock();a.update(s);
  for(let i=0;i<100&&(a.music.readyState<2||a.music.paused);i++)await wait(50);
  check(a.music.src.endsWith('/assets/audio/Blues%20Shuffle%20Loop.mp3'),'Arquivo correto');check(a.music.duration>130&&a.music.duration<140,'MP3 real decodificado');check(a.music.loop&&!a.music.paused,'Reprodução em loop');check(Math.abs(a.music.volume-.14)<.001,'Volume mestre aplicado');
  const start=a.music.currentTime;await wait(200);check(a.music.currentTime>start,'Relógio da trilha avança');
  a.event('jump');check(a.voices.size>0,'Efeito de salto preservado');a.update(s,true);check(a.music.paused&&a.voices.size===0,'Pausa congela trilha e efeitos');const frozen=a.music.currentTime;await wait(150);check(Math.abs(a.music.currentTime-frozen)<.05,'Pausa conserva posição');
  a.update(s);await wait(150);check(!a.music.paused&&a.music.currentTime>=frozen,'Retomada');g.audio.setMuted(true);a.update(s);check(a.music.muted&&a.music.paused,'Mudo respeitado');g.audio.setMuted(false);g.audio.setMasterVolume(.8);a.update(s);check(Math.abs(a.music.volume-.28)<.001&&!a.music.muted,'Alteração de volume');
  a.update({stage:'GAME_OVER'});check(a.music.paused,'Derrota pausa');a.update(s);await wait(100);check(!a.music.paused,'Retry retoma');a.update({stage:'COMPLETE'});check(!a.music.paused,'Piquenique mantém trilha');
  a.music.currentTime=a.music.duration-.1;await wait(500);check(a.music.currentTime<2&&!a.music.paused,'Repetição real no fim do MP3');
  a.update(s,true);const play=a.music.play.bind(a.music);a.music.play=()=>Promise.reject(Error('Autoplay bloqueado na fixture'));a.update(s);await wait(20);check(!a.playPending,'Rejeição libera nova tentativa');a.music.play=play;a.unlock();await wait(100);check(!a.music.paused,'Gesto tenta novamente após bloqueio');
  const duration=a.music.duration;a.destroy();check(a.disposed&&a.music.paused&&!a.music.getAttribute('src')&&a.voices.size===0,'Descarte libera mídia e efeitos');a.update(s);a.event('jump');check(a.voices.size===0,'Descarte não recria som');
  const b=new GardenAudio(g.audio);let resolve;b.music.play=()=>new Promise(r=>{resolve=r;});b.update(s);b.destroy();resolve();await wait(0);check(b.music.paused&&!b.music.getAttribute('src'),'Descarte durante play pendente');
  return{resultado:'aprovado',duracao:duration,arquivo:'Blues Shuffle Loop.mp3',loop:true,pausa:true,mudo:true,volume:true,efeitos:true,descarte:true,autoplay:true};
 })()`);console.log(JSON.stringify(result,null,2));
}finally{ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
